// CPU projection fallback for environments without a WebGL context.
// Three.js scene/camera and picking remain shared with the primary WebGL renderer.
import * as THREE from 'three';
export class CanvasProjectionRenderer {
 constructor(){this.domElement=document.createElement('canvas');this.ctx=this.domElement.getContext('2d');this.ratio=1;this.width=1;this.height=1;this.vp=[0,0,1,1];this.matrix=new THREE.Matrix4();this.v=new THREE.Vector3();}
 setPixelRatio(x){this.ratio=x;this.setSize(this.width,this.height);}getPixelRatio(){return this.ratio;}
 setSize(w,h){this.width=w;this.height=h;this.domElement.width=Math.max(1,Math.round(w*this.ratio));this.domElement.height=Math.max(1,Math.round(h*this.ratio));this.domElement.style.width=w+'px';this.domElement.style.height=h+'px';}
 setViewport(x,y,w,h){this.vp=[x,y,w,h];}setScissor(){}setScissorTest(){}
 render(scene,camera){const ctx=this.ctx,r=this.ratio,[x,y,w,h]=this.vp;scene.updateMatrixWorld(true);camera.updateMatrixWorld(true);const vp=new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse);const project=(p,m)=>{const v=this.v.fromArray(p).applyMatrix4(m).applyMatrix4(vp);if(v.z < -1||v.z>1)return null;return [x+(v.x+1)*w/2,this.height-y-(v.y+1)*h/2,v.z];};ctx.save();ctx.scale(r,r);ctx.beginPath();ctx.rect(x,this.height-y-h,w,h);ctx.clip();ctx.fillStyle='#'+scene.background.getHexString();ctx.fillRect(x,this.height-y-h,w,h);const jobs=[];
 scene.traverseVisible(o=>{if(o.isLine){const pos=o.geometry.getAttribute('position');if(!pos)return;const mat=o.material;const points=[];for(let i=0;i<pos.count;i++)points.push(project([pos.getX(i),pos.getY(i),pos.getZ(i)],o.matrixWorld));jobs.push({order:o.renderOrder||0,depth:points.filter(Boolean).reduce((a,p)=>a+p[2],0)/Math.max(1,points.length),draw:()=>{ctx.globalAlpha=mat.opacity??1;ctx.strokeStyle=o.type==='GridHelper'?'#32465a':'#'+mat.color.getHexString();ctx.lineWidth=o.userData.strokeWidth||(o.isLineSegments?.65:1.25);ctx.setLineDash(mat.isLineDashedMaterial?[4,3]:[]);ctx.beginPath();let pen=false;for(let i=0;i<points.length;i++){const p=points[i];if(!p){pen=false;continue;}if(!pen||o.isLineSegments&&i%2===0)ctx.moveTo(p[0],p[1]);else ctx.lineTo(p[0],p[1]);pen=true;}ctx.stroke();ctx.setLineDash([]);}});}else if(o.isMesh){const count=o.isInstancedMesh?o.count:1;for(let i=0;i<count;i++){let world=o.matrixWorld,color=o.material.color;if(o.isInstancedMesh){const m=new THREE.Matrix4();o.getMatrixAt(i,m);world=new THREE.Matrix4().multiplyMatrices(o.matrixWorld,m);color=new THREE.Color();o.getColorAt(i,color);}const p=project([0,0,0],world);if(!p)continue;const rad=o.geometry.parameters.radius??.05;const edge=project([rad,0,0],world);const size=Math.max(o.isInstancedMesh?2:2.5,edge?Math.hypot(edge[0]-p[0],edge[1]-p[1]):3);const fill='#'+color.getHexString();jobs.push({order:o.renderOrder||0,depth:p[2],draw:()=>{ctx.globalAlpha=o.material.opacity??1;ctx.fillStyle=fill;ctx.beginPath();ctx.arc(p[0],p[1],Math.min(35,size),0,Math.PI*2);ctx.fill();}});}}});jobs.sort((a,b)=>(a.order||0)-(b.order||0)||b.depth-a.depth);for(const job of jobs)job.draw();ctx.restore();}
}
